// 16x16 toroid (periodic) game of life
module TopModule(
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);
    reg [255:0] r;
    wire [255:0] next;
    integer i;
    wire [7:0] n;
    reg [7:0] ns [0:15];
    for (i = 0; i < 16; i = i + 1) begin
        Neighbours neighb(r, i, ns);
    end
    generate for (i = 0; i < 16; i = i + 1) begin : b
        assign n = ns[i];
        assign next[i*16 +: 16] = (r[i*16 +: 16] & (n == 2)) | (~r[i*16 +: 16] & (n < 4) & (n > 1));
    end endgenerate
    always @(posedge clk) begin
        if (load) r <= data;
        else r <= next;
    end
    assign q = r;
endmodule

