// 16x16 toroidal game of life, one clock cycle per timestep. Same game as the
// infinite grid version, but the register stage has been removed: the combinational
// next state function directly calculates the state of the next timestep, without
// needing an extra register to make the forward-backward ping-pong chain.
module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
    wire [255:0] next_q;
    reg [255:0] _q;
    genvar i, j;
    for (i = 0; i < 16; i = i + 1) begin
        for (j = 0; j < 16; j = j + 1) begin
            wire [255:0] neighbours;
            neighbours [(i-1)%16*16 + (j-1)%16/16] = _q [(i-1)%16*16 + (j-1)%16/16];
            neighbours [(i-1)%16*16 + (j)%16/16] = _q [(i-1)%16*16 + (j)%16/16];
            neighbours [(i-1)%16*16 + (j+1)%16/16] = _q [(i-1)%16*16 + (j+1)%16/16];
            neighbours [(i)%16*16 + (j-1)%16/16] = _q [(i)%16*16 + (j-1)%16/16];
            neighbours [(i)%16*16 + (j+1)%16/16] = _q [(i)%16*16 + (j+1)%16/16];
            neighbours [(i+1)%16*16 + (j-1)%16/16] = _q [(i+1)%16*16 + (j-1)%16/16];
            neighbours [(i+1)%16*16 + (j)%16/16] = _q [(i+1)%16*16 + (j)%16/16];
            neighbours [(i+1)%16*16 + (j+1)%16/16] = _q [(i+1)%16*16 + (j+1)%16/16];
            neighbours [i*16 + j] = _q [i*16 + j];
            wire alive = _q[i*16 + j];
            wire neighbour_count = neighbours[0] + neighbours[1] + neighbours[2] + neighbours[3] + neighbours[4] + neighbours[5] + neighbours[6] + neighbours[7] + neighbours[8] + neighbours[9] + neighbours[10] + neighbours[11] + neighbours[12] + neighbours[13] + neighbours[14] + neighbours[15];
            next_q [i*16 + j] = (neighbour_count == 3) ? 1 : (neighbour_count == 2 ? alive : 0);
        end
    end
    always @(posedge clk) begin
        if (load) _q <= data;
        else _q <= next_q;
    end
    assign q = _q;
endmodule

