// A 16x16 toroid, as described in the docstring.
module Toroid16x16(input [15:0] q [0:15], output [15:0] n [0:15]);
  genvar i, j;
  for (i = 0; i < 16; i = i + 1) begin
    for (j = 0; j < 16; j = j + 1) begin
      // Neighbour indices, wrapped around the toroid.
      wire [15:0] n0 = q[(i+15)&15, j];
      wire [15:0] n1 = q[(i+1)&15, j];
      wire [15:0] n2 = q[(i+15)&15, (j+1)&15];
      wire [15:0] n3 = q[(i+1)&15, (j+1)&15];
      wire [15:0] n4 = q[(i+15)&15, (j+15)&15];
      wire [15:0] n5 = q[(i+1)&15, (j+15)&15];
      wire [15:0] n6 = q[(i+15)&15, (j+1)&15];
      wire [15:0] n7 = q[(i+1)&15, (j+15)&15];
      // Neighbour count (0-7).
      wire [2:0] nc = n0 + n1 + n2 + n3 + n4 + n5 + n6 + n7;
      // Game logic: one combinatorial multicube.
      assign n[i, j] = (q[i, j] & ((nc == 2) | (nc == 3))) |
                       ((~q[i, j]) & (nc == 3));
    end
  end
endmodule

