module TopModule (
  input  clk,
  input  load,
  input  [255:0] data,
  output [255:0] q
);
  reg [255:0] r;
  wire [255:0] n;
  genvar i, j;
  generate
    for (i = 0; i < 16; i = i + 1) begin : row
      for (j = 0; j < 16; j = j + 1) begin : col
        NeighbourCount nc (
          .clk(clk),
          .load(load),
          .data(data),
          .q(n[i*16+j]),
          .x(i),
          .y(j)
        );
      end
    end
  endgenerate
  always @(posedge clk) begin
    if (load) r <= data;
    else begin
      reg [255:0] next;
      genvar i, j;
      for (i = 0; i < 16; i = i + 1) begin : row
        for (j = 0; j < 16; j = j + 1) begin : col
          next[i*16+j] = (n[i*16+j] == 3 || (n[i*16+j] == 2 && r[i*16+j])) ? 1 : 0;
        end
      end
      r <= next;
    end
  end
  assign q = r;
endmodule

