// 16x16 toroidal game of life
module TopModule (
    input  wire        clk,
    input  wire        load,
    input  wire [255:0] data,
    output wire [255:0] q
);
    reg [255:0] r;
    wire [255:0] nextr;
    wire [255:0] neighbours;
    wire [7:0] alive_neighbours;
    genvar i, j;
    generate
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                neighbours[i*16+j] = r[(i+15)%16*16+j] + r[(i+1)%16*16+j] +
                                      r[(i+15)%16*16+(j+1)%16] + r[(i+1)%16*16+(j+1)%16] +
                                      r[(i+15)%16*16+(j+15)%16] + r[(i+1)%16*16+(j+15)%16] +
                                      r[(i+15)%16*16+(j-1)%16] + r[(i+1)%16*16+(j-1)%16];
                alive_neighbours[i*16+j] = r[i*16+j] + neighbours[i*16+j];
            end
        end
        for (i = 0; i < 256; i = i + 1) begin
            always @(*) begin
                nextr[i] = r[i];
                if (alive_neighbours[i] < 2 || alive_neighbours[i] > 3) nextr[i] = 1'b0;
                else if (alive_neighbours[i] == 3) nextr[i] = 1'b1;
            end
        end
    endgenerate
    always @(posedge clk) begin
        if (load) r <= data;
        else r <= nextr;
    end
    assign q = r;
endmodule

